CREATE TABLE rendimiento_plantillas (
 id BIGSERIAL PRIMARY KEY, familia UUID NOT NULL DEFAULT gen_random_uuid(),version INTEGER NOT NULL CHECK(version>0),
 empresa_propietaria_id BIGINT REFERENCES empresas(id),codigo VARCHAR(40) NOT NULL,nombre VARCHAR(100) NOT NULL,rubro VARCHAR(100) NOT NULL,
 tipo VARCHAR(20) NOT NULL CHECK(tipo IN ('BASE','PERSONALIZADA')),definicion JSONB NOT NULL,solicitud JSONB,idempotencia UUID UNIQUE,
 creada TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(familia,version),UNIQUE NULLS NOT DISTINCT(empresa_propietaria_id,codigo,version)
);
CREATE TABLE rendimiento_asignaciones (
 id BIGSERIAL PRIMARY KEY,empresa_id BIGINT NOT NULL REFERENCES empresas(id),local_id BIGINT,
 modo VARCHAR(20) NOT NULL CHECK(modo IN ('GENERAL','ESPECIFICO','PERSONALIZADO')),plantilla_id BIGINT NOT NULL REFERENCES rendimiento_plantillas(id),
 FOREIGN KEY(empresa_id,local_id) REFERENCES locales(empresa_id,id),UNIQUE NULLS NOT DISTINCT(empresa_id,local_id)
);
CREATE TABLE actividades (
 id BIGSERIAL PRIMARY KEY,empresa_id BIGINT NOT NULL REFERENCES empresas(id),local_id BIGINT NOT NULL,
 plantilla_id BIGINT NOT NULL REFERENCES rendimiento_plantillas(id),flujo_codigo VARCHAR(40) NOT NULL,flujo_definicion JSONB NOT NULL,
 titulo VARCHAR(200) NOT NULL,detalle VARCHAR(500) NOT NULL DEFAULT '',servicio_id BIGINT REFERENCES productos(id),
 ejecutor_id BIGINT REFERENCES usuarios(id) ON DELETE SET NULL,ejecutor_original_id BIGINT NOT NULL,ejecutor_nombre VARCHAR(150) NOT NULL,
 creador_original_id BIGINT NOT NULL,creador_nombre VARCHAR(150) NOT NULL,estado VARCHAR(40) NOT NULL,version INTEGER NOT NULL DEFAULT 0,
 creada TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,iniciada TIMESTAMPTZ,completada TIMESTAMPTZ,cancelada_en TIMESTAMPTZ,
 finalizada BOOLEAN NOT NULL DEFAULT false,cancelada BOOLEAN NOT NULL DEFAULT false,idempotencia UUID NOT NULL,solicitud JSONB NOT NULL,
 CHECK(NOT(finalizada AND cancelada)),CHECK(finalizada=(completada IS NOT NULL)),CHECK(cancelada=(cancelada_en IS NOT NULL)),
 FOREIGN KEY(empresa_id,local_id) REFERENCES locales(empresa_id,id),UNIQUE(empresa_id,local_id,idempotencia),UNIQUE(empresa_id,local_id,id)
);
CREATE INDEX actividades_local_responsable_fecha ON actividades(empresa_id,local_id,ejecutor_original_id,creada);
CREATE INDEX actividades_local_completada ON actividades(empresa_id,local_id,completada) WHERE finalizada;
CREATE TABLE actividad_eventos (
 id BIGSERIAL PRIMARY KEY,empresa_id BIGINT NOT NULL,local_id BIGINT NOT NULL,actividad_id BIGINT NOT NULL,
 version INTEGER NOT NULL,tipo VARCHAR(40) NOT NULL,estado VARCHAR(40) NOT NULL,actor_original_id BIGINT NOT NULL,actor_nombre VARCHAR(150) NOT NULL,
 ocurrido_en TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,detalle VARCHAR(500) NOT NULL DEFAULT '',
 FOREIGN KEY(empresa_id,local_id,actividad_id) REFERENCES actividades(empresa_id,local_id,id),UNIQUE(actividad_id,version)
);
ALTER TABLE pedidos ADD COLUMN servido_en TIMESTAMPTZ;
ALTER TABLE pedidos ADD COLUMN servido_por_original_id BIGINT;
ALTER TABLE pedidos ADD COLUMN servido_por_nombre VARCHAR(150);
CREATE TABLE reglas_avisos (
 id BIGSERIAL PRIMARY KEY,familia UUID NOT NULL DEFAULT gen_random_uuid(),version INTEGER NOT NULL,
 empresa_id BIGINT REFERENCES empresas(id),local_id BIGINT,perfil_familia UUID,nombre VARCHAR(100) NOT NULL,
 titulo VARCHAR(120) NOT NULL,mensaje VARCHAR(1500) NOT NULL,disparadores JSONB NOT NULL,paginas JSONB NOT NULL,roles JSONB NOT NULL,
 condicion VARCHAR(40) NOT NULL CHECK(condicion IN ('SIEMPRE','SUSCRIPCION_POR_VENCER')),
 frecuencia VARCHAR(20) NOT NULL CHECK(frecuencia IN ('DIA','SESION','UNA_VEZ')),prioridad INTEGER NOT NULL CHECK(prioridad BETWEEN 0 AND 100),
 accion VARCHAR(40) NOT NULL,activa BOOLEAN NOT NULL,desde DATE,hasta DATE,solicitud JSONB,idempotencia UUID UNIQUE,
 FOREIGN KEY(empresa_id,local_id) REFERENCES locales(empresa_id,id),CHECK(local_id IS NULL OR empresa_id IS NOT NULL),CHECK(hasta IS NULL OR desde IS NULL OR hasta>=desde),UNIQUE(familia,version)
);
CREATE TABLE aviso_entregas (
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(),regla_id BIGINT NOT NULL REFERENCES reglas_avisos(id),regla_familia UUID NOT NULL,
 empresa_id BIGINT NOT NULL REFERENCES empresas(id),local_id BIGINT NOT NULL,usuario_id BIGINT REFERENCES usuarios(id) ON DELETE SET NULL,
 usuario_original_id BIGINT NOT NULL,clave_frecuencia VARCHAR(120) NOT NULL,sesion_hash VARCHAR(64) NOT NULL,
 estado VARCHAR(20) NOT NULL CHECK(estado IN ('RESERVADO','MOSTRADO','CERRADO','ACEPTADO','ACCION')),
 reservada_en TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,mostrado_en TIMESTAMPTZ,respondido_en TIMESTAMPTZ,
 FOREIGN KEY(empresa_id,local_id) REFERENCES locales(empresa_id,id),UNIQUE(regla_familia,empresa_id,usuario_original_id,clave_frecuencia)
);
CREATE INDEX aviso_entregas_sesion ON aviso_entregas(empresa_id,usuario_original_id,sesion_hash,estado);
